def min_cut(s):
    n = len(s)
    pal = [[False] * n for _ in range(n)]
    for i in range(n): pal[i][i] = True
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and (length == 2 or pal[i+1][j-1]):
                pal[i][j] = True
    cuts = list(range(n))
    for i in range(n):
        if pal[0][i]:
            cuts[i] = 0
            continue
        for j in range(1, i + 1):
            if pal[j][i]:
                cuts[i] = min(cuts[i], cuts[j-1] + 1)
    return cuts[-1]
